<script setup lang="ts">
const props = defineProps<{
  locale: string
}>()
const emit = defineEmits<{
  (e: 'selectedCategory', id: number): void
}>()
const config = useRuntimeConfig()

interface ICategory {
  id: number,
  image: string,
  name: string,
  langs:
      {
        id: number,
        uuid: string,
        category_id: number,
        title: string,
        lang: string,
        created_at: string,
        updated_at: string
      }[],
}

const {data: categories} = useAsyncData<{ data: ICategory[] }>(
    `categories`,
    async () => {
      const result: {
        data: ICategory[]
      } = await $fetch(`/api/categories/all?per_page=50&page=1`, {
        baseURL: config.public.baseUrl,
      })
      return result;
    }
)
const selectedCategoryId = ref<number | null>(null)
watch(categories, (val) => {
  if (categories.value?.data.length !== 0){
    selectedCategoryId.value=categories.value?.data[0]?.id??0
    emit('selectedCategory', categories.value?.data[0]?.id??0)
  }
}, {
  immediate: true, // Triggers as soon as the component loads
  deep: true       // Ensures nested data changes are caught
})

function selectCategory(id: number) {
  selectedCategoryId.value = id
  emit('selectedCategory', id)
}
</script>

<template>
  <v-list>
    <v-list-item
        v-for="item in categories?.data"
        :key="item.id"
        @click="selectCategory(item.id)"
        :active="selectedCategoryId === item.id"
    >
      <template v-slot:prepend v-if="item.image!==null">
        <v-avatar size="32" rounded="0">
          <v-img
              :src="config.public.baseUrl + '/' + item.image"
              alt="category icon"
              cover
          ></v-img>
        </v-avatar>
      </template>

      <v-list-item-title>
        {{ item.langs.find(l => l.lang === locale)?.title ?? '' }}
      </v-list-item-title>
    </v-list-item>
  </v-list>
</template>

